def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []

    # Extract the 4-connected nonzero objects.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr - 1, cc), (rr + 1, cc),
                               (rr, cc - 1), (rr, cc + 1)):
                    if (0 <= nr < h and 0 <= nc < w and
                            grid[nr][nc] == color and (nr, nc) not in seen):
                        seen.add((nr, nc))
                        stack.append((nr, nc))

            minr = min(rr for rr, _ in cells)
            maxr = max(rr for rr, _ in cells)
            minc = min(cc for _, cc in cells)
            maxc = max(cc for _, cc in cells)
            objects.append({
                "color": color,
                "cells": cells,
                "r": minr,
                "c": minc,
                "bh": maxr - minr + 1,
                "bw": maxc - minc + 1,
            })

    def encloses_empty_cell(obj):
        top, left = obj["r"], obj["c"]
        bh, bw = obj["bh"], obj["bw"]
        filled = {(r - top, c - left) for r, c in obj["cells"]}

        # Flood-fill empty cells reachable from the bounding-box boundary.
        outside = set()
        stack = []
        for rr in range(bh):
            for cc in range(bw):
                if (rr == 0 or rr == bh - 1 or cc == 0 or cc == bw - 1):
                    if (rr, cc) not in filled and (rr, cc) not in outside:
                        outside.add((rr, cc))
                        stack.append((rr, cc))

        while stack:
            rr, cc = stack.pop()
            for nr, nc in ((rr - 1, cc), (rr + 1, cc),
                           (rr, cc - 1), (rr, cc + 1)):
                if (0 <= nr < bh and 0 <= nc < bw and
                        (nr, nc) not in filled and (nr, nc) not in outside):
                    outside.add((nr, nc))
                    stack.append((nr, nc))

        return any((rr, cc) not in filled and (rr, cc) not in outside
                   for rr in range(bh) for cc in range(bw))

    upper = [obj for obj in objects if encloses_empty_cell(obj)]
    lower = [obj for obj in objects if not encloses_empty_cell(obj)]
    placements = []

    def boxes_overlap(obj, row, other, other_row):
        return not (
            row + obj["bh"] <= other_row or
            other_row + other["bh"] <= row or
            obj["c"] + obj["bw"] <= other["c"] or
            other["c"] + other["bw"] <= obj["c"]
        )

    positions = {}

    # Enclosed shapes pack upward; other shapes pack downward.
    for obj in sorted(upper, key=lambda item: item["r"]):
        for row in range(h - obj["bh"] + 1):
            if all(not boxes_overlap(obj, row, other, other_row)
                   for other, other_row in placements):
                positions[id(obj)] = row
                placements.append((obj, row))
                break

    for obj in sorted(lower, key=lambda item: item["r"] + item["bh"],
                      reverse=True):
        for row in range(h - obj["bh"], -1, -1):
            if all(not boxes_overlap(obj, row, other, other_row)
                   for other, other_row in placements):
                positions[id(obj)] = row
                placements.append((obj, row))
                break

    result = [[0] * w for _ in range(h)]
    for obj in objects:
        new_row = positions[id(obj)]
        for r, c in obj["cells"]:
            result[new_row + r - obj["r"]][c] = obj["color"]

    return result
